  DBMS_OUTPUT.PUT_LINE(q'~        ? ' \u00b7 ' + Math.round(f.dtfLo) + '\u2013' + Math.round(f.dtfHi) + ' d' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~    } else if (f.q === 'FLAT') sub = 'no growth';~');
  DBMS_OUTPUT.PUT_LINE(q'~    else if (f.q === 'CYCLIC') sub = 'peaks not growing';~');
  DBMS_OUTPUT.PUT_LINE(q'~    else if (f.slope != null && f.slope <= 0) sub = 'not growing';~');
  DBMS_OUTPUT.PUT_LINE(q'~    else sub = 'beyond the forecast';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { k: 'dtf', l: label, v: f.dtf != null ? fDays(f.dtf) : '\u2013', s: sub, tone: f.dtf == null ? 'muted' : tone };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function stamp(d) { return '<span class="stamp">\u2192 ' + fDay(Math.round(d)) + '</span>'; }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function pctTone(p, warn, crit) { return p == null ? '' : p >= crit ? 'crit' : p >= warn ? 'warn' : ''; }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function tbspcFacts(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ k: 'pct', l: 'Used', v: num(f.pct, 1) + '<small>%</small>', s: m.unit.fmt(f.v) + ' of ' + m.unit.fmt(f.lim),~');
  DBMS_OUTPUT.PUT_LINE(q'~      tone: pctTone(f.pct, K.nfWarn, K.nfCrit) });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.q === 'CYCLIC') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'Cycle peak', v: num(f.cycPk, 1) + '<small>%</small>', s: (f.cycN || 0) + ' purges, every ' + Math.round(f.cycD || 0) + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'Peak growth', v: m.unit.rate(f.pkSlope) });~');
  DBMS_OUTPUT.PUT_LINE(q'~    } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'Growth', v: m.unit.rate(f.slope), s: f.accel != null && f.accel >= 1.5 ? 'accelerating \u00d7' + num(f.accel, 1) : 'fit over ' + (f.n || '\u2013') + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push(dtfFact(f, 'Full in'));~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.need90 > 0) out.push({ l: 'Add for 90 d', v: num(f.need90, 1) + '<small>GiB</small>', s: f.addBy ? 'by ' + fDay(dayN(f.addBy)) : '' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.below) out.push({ l: 'Limit', v: 'below used', tone: 'crit' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function limitFacts(label, limWord) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: label, v: m.unit.fmt(f.v), s: f.lim != null ? 'of ' + m.unit.fmt(f.lim) + ' ' + limWord : 'no limit' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (f.pct != null) out.push({ k: 'pct', l: 'Of ' + limWord, v: num(f.pct, 1) + '<small>%</small>', tone: pctTone(f.pct, SERIES_SAT, 100) });~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: m.unit.rateLabel, v: m.unit.rate(f.slope), s: 'fit over ' + (f.n || '\u2013') + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (f.lim != null) out.push(dtfFact(f, SERIES_SAT + '% in'));~');
  DBMS_OUTPUT.PUT_LINE(q'~      return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~    };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function redoFacts(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var avg = avgLast(m.pts, 7);~');
  DBMS_OUTPUT.PUT_LINE(q'~    return [~');
  DBMS_OUTPUT.PUT_LINE(q'~      { l: 'Today', v: m.unit.fmt(lastVal(m.pts)) },~');
  DBMS_OUTPUT.PUT_LINE(q'~      { l: '7-day average', v: m.unit.fmt(avg) },~');
  DBMS_OUTPUT.PUT_LINE(q'~      { l: m.unit.rateLabel, v: m.unit.rate(f.slope), s: 'fit over ' + (f.n || '\u2013') + ' d' }~');
  DBMS_OUTPUT.PUT_LINE(q'~    ];~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function cpuFacts(m, p95, avg) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ k: 'now', l: 'Busy-hour p95', v: num(f.v, 1) + '<small>%</small>', s: f.hot ? 'at the ' + CPU_SAT + '% line now' : 'of ' + p95,~');
  DBMS_OUTPUT.PUT_LINE(q'~      tone: pctTone(f.v, CPU_SAT * 0.9, CPU_SAT) });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var a = m.fits[avg];~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ l: 'Daily average', v: a ? num(a.v, 1) + '<small>%</small>' : '\u2013' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ l: m.unit.rateLabel, v: m.unit.rate(f.slope), s: f.sig === 0 ? 'not significant' : 'fit over ' + (f.n || '\u2013') + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push(dtfFact(f, CPU_SAT + '% in'));~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function hostCpuFacts(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var out = cpuFacts(m, 'host CPU', 'BUSY_PCT');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var pk = m.fits.BUSY_PEAK;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (pk) out.splice(2, 0, { l: 'Peak window', v: num(pk.v, 1) + '<small>%</small>', s: 'business hours' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function dbCpuFacts(m) { return cpuFacts(m, 'host CPUs', 'DB_CPU_PCT'); }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function lastVal(pts) { for (var i = pts.length - 1; i >= 0; i--) if (pts[i].y != null) return pts[i].y; return null; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function avgLast(pts, n) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var s = 0, c = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) { if (p.y != null && p.x > LAST - n) { s += p.y; c++; } });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return c ? s / c : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- alert and anomaly wording (facts only) ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function alertWhen(a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (a.unit === 'DAYS' || a.u === 'DAYS') return stamp(LAST + a.v);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (/_ANOM$/.test(a.kind)) return '<span class="when">' + fDay(dayN(a.n > 1 ? a.first : a.day)) + (a.n > 1 ? '\u2013' + fDay(dayN(a.day)) : '') + '</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<span class="when">now</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function alertFact(a, m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var u = m ? m.unit : unitFor(a.u);~');
  DBMS_OUTPUT.PUT_LINE(q'~    switch (a.kind) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'TBSPC_FULL': return 'full in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'CPU_SAT': case 'DBCPU_SAT': return CPU_SAT + '% busy in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'SERIES_LIMIT': return SERIES_SAT + '% of limit in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'TBSPC_NEARFULL': return '<b>' + num(a.v, 1) + '%</b> used';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'SERIES_NEARLIMIT': return '<b>' + num(a.v, 1) + '%</b> of limit';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'CPU_HOT': case 'DBCPU_HOT': return 'busy-hour p95 <b>' + num(a.v, 1) + '%</b> now';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'CPU_SHIFT': return 'level shift <b>' + sign(a.v) + num(Math.abs(a.v), 1) + '%</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'DATA_STALE': return 'no AWR snapshot for <b>' + auto(a.v) + ' h</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'MODEL_HEALTH': return 'ESM model ' + esc(a.msg || '');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (/_ANOM$/.test(a.kind)) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var v = a.u === 'BYTES' ? fBytes(a.v) + '/d' : a.u === 'PCT' ? num(a.v, 1) + '%' : a.u === 'GIB' ? auto(a.v) + ' GiB/d' : auto(a.v);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var t = a.u === 'BYTES' ? fBytes(a.thr) + '/d' : a.u === 'PCT' ? num(a.thr, 1) + '%' : a.u === 'GIB' ? auto(a.thr) + ' GiB/d' : auto(a.thr);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var span = a.n > 1 ? ' \u00b7 ' + a.n + ' days' : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~      return 'unusual <b>' + v + '</b>, normal \u2264 ' + t + (a.maxz != null ? ' \u00b7 z ' + num(a.maxz, 1) : '') + span;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return esc(a.msg || a.kind);~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* One chip per flagged day: the day verdict (worst mode) plus its flagged hours. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function anomalyEvents(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var days = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    m.anoms.forEach(function (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (a.ak === 'CPU_SHIFT') return;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var d = dayN(a.ts);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (d <= LAST - ANOM_DAYS) return;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var e = days[d] || (days[d] = { d: d, day: null, hours: {}, nh: 0, f: a.f, z: 0 });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (a.grain === 'HOUR') {~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (!e.hours[a.ts]) e.nh++;~');
  DBMS_OUTPUT.PUT_LINE(q'~        e.hours[a.ts] = a.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else if (!e.day || Math.abs(a.z) > Math.abs(e.day.z)) e.day = a;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (Math.abs(a.z || 0) >= Math.abs(e.z)) { e.z = a.z; e.f = a.f; }~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return Object.keys(days).map(function (k) { return days[k]; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return b.d - a.d; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function anomalyChip(ev, m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var val = '', usual = '', a = ev.day;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (m.fam.id === 'tablespaces' || m.f.s === 'DB_SIZE_GB') {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var scale = m.fam.id === 'tablespaces' ? 1 : Math.pow(1024, 3);~');
  DBMS_OUTPUT.PUT_LINE(q'~        val = sign(a.v) + fBytes(Math.abs(a.v * scale)) + ' in a day';~');
  DBMS_OUTPUT.PUT_LINE(q'~        usual = 'usual ' + fBytes(a.e * scale);~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~        val = m.unit.fmt(a.v);~');
  DBMS_OUTPUT.PUT_LINE(q'~        usual = 'usual ' + m.unit.fmt(a.e);~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (ev.nh) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var hrs = ev.nh + ' h ' + (ev.f === 'LOW' ? 'below' : 'above') + ' their usual hour';~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (val) usual += ' \u00b7 ' + hrs; else val = hrs;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="an ' + (ev.f === 'LOW' ? 'lo' : 'hi') + '"><span class="dt">' + fWDay(ev.d) + '</span><span class="vv">' + val +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '</span><span class="us">' + usual + '</span><span class="z">z ' + num(ev.z, 1) + '</span></div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- charts ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var CHARTS = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~  var W = 640, H = 196, ML = 44, MR = 14, MT = 22, MB = 24;~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function niceTicks(lo, hi, n) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var span = hi - lo || 1, step = Math.pow(10, Math.floor(Math.log10(span / n)));~');
  DBMS_OUTPUT.PUT_LINE(q'~    var err = span / n / step;~');
  DBMS_OUTPUT.PUT_LINE(q'~    step *= err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t = [], v = Math.ceil(lo / step) * step;~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (; v <= hi + step * 1e-9; v += step) t.push(+v.toFixed(10));~');
  DBMS_OUTPUT.PUT_LINE(q'~    var dp = Math.max(0, -Math.floor(Math.log10(step) + 1e-9));~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { ticks: t, step: step, dp: dp };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function forecastKnots(m, method) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return m.fc.filter(function (r) { return r.m === method; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .map(function (r) { return { x: dayN(r.t), y: r.v, lo: r.lo, hi: r.hi }; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return a.x - b.x; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function horizon(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, h = 90;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var reach = m.fc.reduce(function (r, k) { return k.m === 'REGR' ? Math.max(r, k.h) : r; }, 30);~');
END;
/
BEGIN
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtf != null && f.dtf > 60 && f.dtf <= 330) h = Math.ceil((f.dtf + 20) / 30) * 30;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return Math.min(h, reach);~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function isHot(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtf != null && f.q === 'OK' && f.dtf <= K.dtfWarn) return true;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.k === 'TBSPC') return f.pct >= K.nfWarn;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.k === 'SERIES') return f.pct >= SERIES_SAT;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return !!f.hot;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function limitLines(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.f.k === 'CPU') out.push({ y: CPU_SAT, cls: 'thr', label: CPU_SAT + '%', target: true });~');
  DBMS_OUTPUT.PUT_LINE(q'~    else if (f.lim != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ y: f.lim, cls: 'lim', label: 'limit ' + m.unit.fmt(f.lim), target: m.f.k === 'TBSPC' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (m.f.k === 'SERIES') out.push({ y: f.lim * SERIES_SAT / 100, cls: 'thr', label: SERIES_SAT + '%', target: true });~');
  DBMS_OUTPUT.PUT_LINE(q'~      else if (K.nfWarn) out.push({ y: f.lim * K.nfWarn / 100, cls: 'thr', label: K.nfWarn + '%' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function chartSpec(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var lines = (m.fam.lines || [[m.f.s, '']]).map(function (l, i) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      return { s: l[0], label: l[1], pts: PTS[key(m.f.k, m.f.dbid, m.f.con, l[0])] || [], role: i };~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).filter(function (l) { return l.pts.length; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return {~');
  DBMS_OUTPUT.PUT_LINE(q'~      hot: isHot(m),~');
  DBMS_OUTPUT.PUT_LINE(q'~      lines: lines, fc: forecastKnots(m, 'REGR'), esm: forecastKnots(m, 'ESM'),~');
  DBMS_OUTPUT.PUT_LINE(q'~      limits: limitLines(m), unit: m.unit, x0: FIRST != null ? FIRST : (lines[0] && lines[0].pts[0] ? lines[0].pts[0].x : LAST - 90),~');
  DBMS_OUTPUT.PUT_LINE(q'~      x1: LAST + horizon(m), pctAxis: m.f.k === 'CPU', m: m~');
  DBMS_OUTPUT.PUT_LINE(q'~    };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function chartSvg(spec, id) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var xs = function (x) { return ML + (x - spec.x0) / (spec.x1 - spec.x0) * (W - ML - MR); };~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ymax = 0, ymin = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.lines.forEach(function (l) { l.pts.forEach(function (p) { if (p.y != null) { ymax = Math.max(ymax, p.y); ymin = Math.min(ymin, p.y); } }); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.limits.forEach(function (l) { ymax = Math.max(ymax, l.y); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.fc.forEach(function (k) { if (k.x <= spec.x1) ymax = Math.max(ymax, k.hi != null ? k.hi : k.y); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (spec.pctAxis) ymax = Math.max(ymax, CPU_SAT);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var sc = spec.unit.scale;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var nt = niceTicks(ymin / sc, (ymax || 1) * 1.06 / sc, 4);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var top = nt.ticks[nt.ticks.length - 1] * sc;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (top < ymax * 1.02) top = (nt.ticks[nt.ticks.length - 1] + nt.step) * sc;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var bot = Math.min(0, nt.ticks[0] * sc);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ys = function (y) { return MT + (1 - (y - bot) / (top - bot || 1)) * (H - MT - MB); };~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(spec.m.name) + '">');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<defs><clipPath id="c' + id + '"><rect x="' + ML + '" y="0" width="' + (W - ML - MR) + '" height="' + (H - MB) + '"/></clipPath></defs>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    nt.ticks.forEach(function (t) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var y = ys(t * sc);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (t * sc > top + 1e-9) return;~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<line x1="' + ML + '" x2="' + (W - MR) + '" y1="' + y.toFixed(1) + '" y2="' + y.toFixed(1) + '" stroke="var(--line-2)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (ML - 6) + '" y="' + (y + 3.5).toFixed(1) + '" text-anchor="end">' + num(t, nt.dp) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<text x="' + (ML - 6) + '" y="10" text-anchor="end">' + esc(spec.unit.short) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var months = monthTicks(spec.x0, spec.x1);~');
  DBMS_OUTPUT.PUT_LINE(q'~    months.forEach(function (mt) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = xs(mt.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<line x1="' + x.toFixed(1) + '" x2="' + x.toFixed(1) + '" y1="' + (H - MB) + '" y2="' + (H - MB + 4) + '" stroke="var(--line)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + x.toFixed(1) + '" y="' + (H - 7) + '" text-anchor="middle">' + mt.label + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<line x1="' + ML + '" x2="' + (W - MR) + '" y1="' + ys(bot).toFixed(1) + '" y2="' + ys(bot).toFixed(1) + '" stroke="var(--line)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<g clip-path="url(#c' + id + ')">');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var fc = spec.fc;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fc.length > 1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var band = fc.filter(function (k) { return k.lo != null && k.hi != null; });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (band.length > 1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var first = fc[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~        var poly = [[first.x, first.y]].concat(band.map(function (k) { return [k.x, k.hi]; }))~');
  DBMS_OUTPUT.PUT_LINE(q'~          .concat(band.slice().reverse().map(function (k) { return [k.x, k.lo]; }));~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<path d="M' + poly.map(function (p) { return xs(p[0]).toFixed(1) + ',' + ys(p[1]).toFixed(1); }).join('L') + 'Z" fill="var(--band)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.lines.slice().reverse().forEach(function (l) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var d = pathOf(l.pts, xs, ys);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (l.role === 0) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var area = areaOf(l.pts, xs, ys, ys(Math.max(bot, 0)));~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (area) o.push('<path d="' + area + '" fill="var(--data-fill)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<path d="' + d + '" fill="none" stroke="var(--data)" stroke-width="1.8" stroke-linejoin="round"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<path d="' + d + '" fill="none" stroke="var(--data-2)" stroke-width="1.3" stroke-linejoin="round"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fc.length > 1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<path d="M' + fc.map(function (k) { return xs(k.x).toFixed(1) + ',' + ys(k.y).toFixed(1); }).join('L') + '" fill="none" stroke="var(--data)" stroke-width="1.6" stroke-dasharray="5 4"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.limits.forEach(function (l) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var y = ys(l.y).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var col = !spec.hot ? 'var(--ink-3)' : l.cls === 'lim' ? 'var(--limit)' : 'var(--thresh)';~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<line x1="' + ML + '" x2="' + (W - MR) + '" y1="' + y + '" y2="' + y + '" stroke="' + col + '" stroke-width="1" stroke-dasharray="' + (l.cls === 'lim' ? '6 4' : '2 3') + '"' + (spec.hot ? '' : ' opacity=".7"') + '/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var cross = crossing(spec);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (cross) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<circle cx="' + xs(cross.x).toFixed(1) + '" cy="' + ys(cross.y).toFixed(1) + '" r="3.5" fill="' + (spec.hot ? 'var(--limit)' : 'var(--ink-2)') + '" stroke="var(--surface)" stroke-width="2"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.esm.forEach(function (k) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = xs(k.x), y = ys(k.y);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (k.lo != null && k.hi != null && (k.hi - k.lo) < (top - bot) * 0.6) o.push('<line x1="' + x.toFixed(1) + '" x2="' + x.toFixed(1) + '" y1="' + ys(k.lo).toFixed(1) + '" y2="' + ys(k.hi).toFixed(1) + '" stroke="var(--esm)" stroke-width="1.5"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<rect x="' + (x - 4).toFixed(1) + '" y="' + (y - 4).toFixed(1) + '" width="8" height="8" fill="var(--esm)" transform="rotate(45 ' + x.toFixed(1) + ' ' + y.toFixed(1) + ')"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.lines.forEach(function (l) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      l.pts.forEach(function (p) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (p.a === 1 || p.a === -1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          var recent = p.x > LAST - ANOM_DAYS;~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (recent) o.push('<circle cx="' + xs(p.x).toFixed(1) + '" cy="' + ys(p.y).toFixed(1) + '" r="3" fill="var(--surface)" stroke="' + (p.a === 1 ? 'var(--crit)' : 'var(--accent)') + '" stroke-width="1.5"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~          else o.push('<circle cx="' + xs(p.x).toFixed(1) + '" cy="' + ys(p.y).toFixed(1) + '" r="1.75" fill="var(--ink-3)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~        }~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</g>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tx = xs(LAST).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<line x1="' + tx + '" x2="' + tx + '" y1="' + MT + '" y2="' + (H - MB) + '" stroke="var(--ink-3)" stroke-width="1" stroke-dasharray="1 3"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<text x="' + tx + '" y="10" text-anchor="middle">today</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.limits.forEach(function (l) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var y = ys(l.y), lim = l.cls === 'lim';~');
  DBMS_OUTPUT.PUT_LINE(q'~      var tc = !spec.hot ? 'var(--ink-3)' : lim ? 'var(--limit)' : 'var(--thresh)';~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (lim ? W - MR - 2 : ML + 4) + '" y="' + (y + (lim ? -4 : 11)).toFixed(1) + '" text-anchor="' + (lim ? 'end' : 'start') + '" class="lbl" style="fill:' + tc + '">' + esc(l.label) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (cross) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (xs(cross.x) - 6).toFixed(1) + '" y="' + (ys(cross.y) + 15).toFixed(1) + '" text-anchor="end" class="stmp" style="fill:' + (spec.hot ? 'var(--limit)' : 'var(--ink-2)') + '">\u2192 ' + fDay(Math.round(cross.x)) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<line class="hx" x1="0" x2="0" y1="' + MT + '" y2="' + (H - MB) + '" stroke="var(--ink-2)" stroke-width="1" visibility="hidden"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<circle class="hd" r="4" fill="var(--data)" stroke="var(--surface)" stroke-width="2" visibility="hidden"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<rect x="' + ML + '" y="0" width="' + (W - ML - MR) + '" height="' + (H - MB) + '" fill="transparent" class="hit"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</svg>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.xs = xs; spec.ys = ys;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function crossing(spec) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var lim = spec.limits.filter(function (l) { return l.target; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!lim || spec.fc.length < 2) return null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var fc = spec.fc;~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (var i = 1; i < fc.length; i++) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var a = fc[i - 1], b = fc[i];~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (a.y < lim.y && b.y >= lim.y) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var x = a.x + (lim.y - a.y) / (b.y - a.y) * (b.x - a.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~        return x <= spec.x1 ? { x: x, y: lim.y } : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return null;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function pathOf(pts, xs, ys) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var d = '', pen = false, prev = null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (p.y == null || (prev != null && p.x - prev > 1.5)) pen = false;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (p.y != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        d += (pen ? 'L' : 'M') + xs(p.x).toFixed(1) + ',' + ys(p.y).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~        pen = true;~');
  DBMS_OUTPUT.PUT_LINE(q'~        prev = p.x;~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return d;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function areaOf(pts, xs, ys, base) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var v = pts.filter(function (p) { return p.y != null; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (v.length < 2) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return 'M' + xs(v[0].x).toFixed(1) + ',' + base.toFixed(1) + v.map(function (p) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      return 'L' + xs(p.x).toFixed(1) + ',' + ys(p.y).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).join('') + 'L' + xs(v[v.length - 1].x).toFixed(1) + ',' + base.toFixed(1) + 'Z';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function monthTicks(x0, x1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var out = [], d = dateOf(x0);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var y = d.getUTCFullYear(), mo = d.getUTCMonth() + 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var span = x1 - x0, every = span > 400 ? 3 : span > 200 ? 2 : 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (;;) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (mo > 11) { mo = 0; y++; }~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = Date.UTC(y, mo, 1) / MS_DAY;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (x > x1) break;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (mo % every === 0) out.push({ x: x, label: mo === 0 ? MONTHS[0] + ' \u2019' + String(y).slice(2) : MONTHS[mo] });~');
  DBMS_OUTPUT.PUT_LINE(q'~      mo++;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function legendHtml(spec) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (spec.lines.length > 1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<span><i></i>' + esc(spec.lines[0].label) + '</span>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<span><i class="l2"></i>' + esc(spec.lines[1].label) + '</span>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.length ? '<div class="legend">' + o.join('') + '</div>' : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function sparkSvg(m, w, h) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var spec = chartSpec(m);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var l = spec.lines[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!l) return '<svg viewBox="0 0 ' + w + ' ' + h + '"></svg>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var x0 = Math.max(spec.x0, LAST - 120), x1 = LAST + 30;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ymax = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~    l.pts.forEach(function (p) { if (p.x >= x0 && p.y != null) ymax = Math.max(ymax, p.y); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    spec.limits.slice(0, 1).forEach(function (lim) { ymax = Math.max(ymax, lim.y); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (spec.pctAxis) ymax = Math.max(ymax, 100);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var xs = function (x) { return 1 + (x - x0) / (x1 - x0) * (w - 2); };~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ys = function (y) { return h - 2 - y / (ymax * 1.05 || 1) * (h - 4); };~');
  DBMS_OUTPUT.PUT_LINE(q'~    var pts = l.pts.filter(function (p) { return p.x >= x0; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<svg viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none" aria-hidden="true">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var area = areaOf(pts, xs, ys, h - 1);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (area) o.push('<path d="' + area + '" fill="var(--data-fill)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<path d="' + pathOf(pts, xs, ys) + '" fill="none" stroke="var(--data)" stroke-width="1.4" vector-effect="non-scaling-stroke"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var fc = spec.fc.filter(function (k) { return k.x <= x1 + 60; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fc.length > 1) o.push('<path d="M' + fc.map(function (k) { return xs(k.x).toFixed(1) + ',' + ys(k.y).toFixed(1); }).join('L') + '" fill="none" stroke="var(--data)" stroke-width="1.2" stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (spec.limits[0]) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var y = ys(spec.limits[0].y).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<line x1="0" x2="' + w + '" y1="' + y + '" y2="' + y + '" stroke="var(--ink-3)" stroke-width="1" stroke-dasharray="2 3" vector-effect="non-scaling-stroke"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if ((p.a === 1 || p.a === -1) && p.x > LAST - ANOM_DAYS) o.push('<circle cx="' + xs(p.x).toFixed(1) + '" cy="' + ys(p.y).toFixed(1) + '" r="2" fill="' + (p.a === 1 ? 'var(--crit)' : 'var(--accent)') + '"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</svg>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- hour heat strip (CPU) ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function heatSvg(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var h = HOURS[key(m.f.dbid, m.f.con, m.fam.heat)];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!h || !h.d.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t0 = dayN(h.t0), rows = 14, cw = 21, rh = 13, lw = 70, top = 2;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var w = lw + cw * 24, ht = top + rows * rh + 16;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var grid = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    h.d.forEach(function (r) { grid[r[0] + '|' + r[1]] = r; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<svg viewBox="0 0 ' + w + ' ' + ht + '" role="img" aria-label="hourly CPU, last 14 days">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (var r = 0; r < rows; r++) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var day = t0 + r, y = top + r * rh;~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (lw - 6) + '" y="' + (y + rh - 3) + '" text-anchor="end">' + fWDay(day) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      for (var c = 0; c < 24; c++) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var cell = grid[r + '|' + c], x = lw + c * cw;~');
  DBMS_OUTPUT.PUT_LINE(q'~        var fill = 'var(--heat-0)', stroke = '';~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (cell && cell[2] != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          var v = Math.max(0, Math.min(100, cell[2]));~');
  DBMS_OUTPUT.PUT_LINE(q'~          fill = 'color-mix(in oklab, var(--heat-1) ' + Math.round(v) + '%, var(--heat-0))';~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (cell[3] === 1) stroke = ' stroke="var(--crit)" stroke-width="2"';~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (cell[3] === -1) stroke = ' stroke="var(--accent)" stroke-width="2"';~');
  DBMS_OUTPUT.PUT_LINE(q'~        }~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<rect class="hc" data-d="' + day + '" data-h="' + c + '" data-v="' + (cell && cell[2] != null ? cell[2] : '') + '" data-f="' + (cell ? cell[3] : 0) + '" x="' + (x + 0.5) + '" y="' + (y + 0.5) + '" width="' + (cw - 1) + '" height="' + (rh - 1) + '" rx="1.5" fill="' + fill + '"' + stroke + '/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    [0, 6, 12, 18].forEach(function (hr) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (lw + hr * cw + cw / 2) + '" y="' + (top + rows * rh + 12) + '" text-anchor="middle">' + (hr < 10 ? '0' : '') + hr + ':00</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</svg>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="heat"><div class="hh"><span>Hourly, last 14 days, by hour ending</span><span class="ramp">0%<i></i>100%</span></div>' + o.join('') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- page pieces ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function pill(sev, text) { return '<span class="st ' + SEV_CLASS[sev] + '">' + esc(text || SEV_LABEL[sev]) + '</span>'; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function sdot(sev) { return '<span class="dot ' + SEV_CLASS[sev] + '"></span>'; }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function factsHtml(facts) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="facts">' + facts.map(function (f) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      return '<div class="fact ' + (f.tone || '') + '"><div class="l">' + esc(f.l) + '</div><div class="v">' + f.v + '</div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (f.s ? '<div class="s">' + esc(f.s) + '</div>' : '') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).join('') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function tagsHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (QUALITY_TAG[m.f.q]) t.push(QUALITY_TAG[m.f.q]);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.f.cur === 0) t.push('no longer reported');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.f.limSrc && m.f.limSrc !== 'MAXBYTES' && m.f.limSrc !== 'AUTOEXTEND' && m.fam.id === 'tablespaces') t.push('limit: ' + m.f.limSrc.toLowerCase());~');
  DBMS_OUTPUT.PUT_LINE(q'~    return t.map(function (x) { return '<span class="tag">' + esc(x) + '</span>'; }).join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function cardHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var spec = chartSpec(m);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var id = CHARTS.length;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var svg = chartSvg(spec, id);~');
  DBMS_OUTPUT.PUT_LINE(q'~    CHARTS.push(spec);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<article class="card ' + SEV_CLASS[m.sev] + (m.fam.heat ? ' split' : '') + '" id="' + m.id + '">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<div class="ch"><h3>' + esc(m.name) + '</h3>' + (m.ctr && m.ctr !== m.name ? '<span class="ctr">' + esc(m.ctr) + '</span>' : '') + tagsHtml(m) + pill(m.sev) + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var va = m.alerts[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (va && (m.sev === 'CRIT' || m.sev === 'WARN')) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<p class="verdict ' + SEV_CLASS[m.sev] + '">' + alertFact(va, m) + ' \u00b7 ' + alertWhen(va) + '</p>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push(factsHtml(m.facts));~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<div class="viz"><div><div class="chart" data-chart="' + id + '">' + svg + '<div class="tip"></div></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push(legendHtml(spec) + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.fam.heat) o.push(heatSvg(m));~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var shifts = m.anoms.filter(function (a) { return a.ak === 'CPU_SHIFT'; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var evs = anomalyEvents(m);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (shifts.length || evs.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<div class="issues">');~');
