  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<div class="iss">' + sdot(a.sev && SEV_RANK[a.sev] != null ? a.sev : 'INFO') + '<span>Level shift <b>' + sign(a.shift) + num(Math.abs(a.shift), 1) + '%</b> since ' + fDay(dayN(a.ts)) + '</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (evs.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var shown = evs.slice(0, 3);~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<div class="anoms"><div class="ah"><span>Unusual days</span><span>' + evs.length + ' in the last ' + ANOM_DAYS + ' d</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~          shown.map(function (e) { return anomalyChip(e, m); }).join('') + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</article>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function rowHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var pct = f.pct != null ? Math.max(0, Math.min(100, f.pct)) : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tone = pctTone(f.pct, m.fam.id === 'tablespaces' ? K.nfWarn : SERIES_SAT, m.fam.id === 'tablespaces' ? K.nfCrit : 100);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var dtf = dtfFact(f, '');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="row" id="' + m.id + '"><div class="nm"><b>' + esc(m.name) + '</b><span>' + esc(m.ctr) + (QUALITY_TAG[f.q] ? ' \u00b7 ' + QUALITY_TAG[f.q] : '') + '</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      sparkSvg(m, 200, 30) +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="c keep">' + (pct != null ? num(f.pct, 1) + '%<div class="bar"><i class="' + tone + '" style="width:' + pct + '%"></i></div>' : m.unit.fmt(f.v)) + '</div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="c">' + m.unit.rate(f.slope) + '<span>growth</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="c">' + dtf.v + '<span>' + esc(dtf.s) + '</span></div>' + pill(m.sev) + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function familySummary(fam, ms) {~');
