  DBMS_OUTPUT.PUT_LINE(q'~    ms.forEach(function (m) { if (c[m.sev] != null) c[m.sev]++; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var parts = ['<b>' + ms.length + '</b> ' + fam.noun + (ms.length === 1 ? '' : 's')];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (c.CRIT) parts.push('<b>' + c.CRIT + '</b> critical');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (c.WARN) parts.push('<b>' + c.WARN + '</b> warning');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var soon = ms.filter(function (m) { return m.f.dtf != null && m.f.q === 'OK'; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return a.f.dtf - b.f.dtf; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (soon && fam.id !== 'redo') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var what = fam.id === 'tablespaces' ? 'full' : fam.id.indexOf('cpu') >= 0 ? CPU_SAT + '%' : SERIES_SAT + '%';~');
  DBMS_OUTPUT.PUT_LINE(q'~      parts.push('soonest ' + what + ': <b>' + esc(soon.name) + '</b> in ' + fDays(soon.f.dtf));~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return parts.map(function (p) { return '<span>' + p + '</span>'; }).join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function headline(fam, ms) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var m = ms[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!m) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var a = m.alerts[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (a && m.sev !== 'OK') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var fact = /_ANOM$/.test(a.kind) ? 'unusual ' + fDay(dayN(a.day)) : alertFact(a, m).replace(/<\/?b>/g, '');~');
  DBMS_OUTPUT.PUT_LINE(q'~      return '<b>' + esc(m.name) + '</b> ' + fact;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fam.id === 'tablespaces') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var full = ms.slice().sort(function (x, y) { return (y.f.pct || 0) - (x.f.pct || 0); })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~      return 'fullest <b>' + esc(full.name) + '</b> ' + num(full.f.pct, 1) + '%';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.k === 'CPU') return '<b>' + esc(m.name) + '</b> p95 ' + num(f.v, 1) + '%';~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fam.id === 'redo') return '<b>' + m.unit.fmt(lastVal(m.pts)) + '</b> today';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<b>' + esc(m.name) + '</b> ' + m.unit.fmt(f.v) + (f.pct != null ? ' \u00b7 ' + num(f.pct, 1) + '%' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- overview: space growth rates ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var SPACE_TOP = 5;~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function famMetrics(id) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var s = sections.filter(function (x) { return x.fam.id === id; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    return s ? s.ms : [];~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  /* The rate a tablespace fills at: a cyclic one is judged on its peaks. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function fillRate(f) { return f.q === 'CYCLIC' ? f.pkSlope : f.slope; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function observedChange(pts, days) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var last = null, first = null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (var i = pts.length - 1; i >= 0; i--) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var p = pts[i];~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (p.y == null) continue;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (last == null) last = p;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (p.x >= last.x - days) first = p; else break;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return last && first && last.x > first.x ? { d: last.y - first.y, n: last.x - first.x } : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function spaceRow(m, cells) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<a class="grow" href="#' + m.id + '"><span class="s">' + esc(m.name) + ' <span>' + esc(m.ctr) +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (QUALITY_TAG[m.f.q] ? ' \u00b7 ' + QUALITY_TAG[m.f.q] : '') + '</span></span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      cells.map(function (c) { return '<span class="c">' + c + '</span>'; }).join('') + '</a>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* The tablespace with the fewest days to full, as one sentence. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function fillsFirstHtml(ts) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var first = ts.filter(function (m) { return m.f.dtf != null && m.f.q !== 'INSUFFICIENT_HISTORY'; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return a.f.dtf - b.f.dtf; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!first) return '<div class="lead">No tablespace is on course to fill.</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = first.f, tone = dtfFact(f, '').tone;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<a class="lead" href="#' + first.id + '">Fills first: <b>' + esc(first.name) + '</b> <span>' + esc(first.ctr) +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (QUALITY_TAG[f.q] ? ' \u00b7 ' + QUALITY_TAG[f.q] : '') + '</span>, ' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (f.dtf > 3650 ? 'full <b>not in sight</b>' : 'full in <b class="' + (tone || '') + '">' + fDays(f.dtf) + '</b> (' + (f.dtf > 120 ? Math.round(f.dtf) + ' d, ' : '') + 'by ' + fDayY(Math.round(LAST + f.dtf)) + ')') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      ' at ' + first.unit.rate(fillRate(f)) + ', ' + num(f.pct, 1) + '% used now</a>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function spaceHtml() {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ts = famMetrics('tablespaces'), dbs = famMetrics('db-size');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!ts.length && !dbs.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var out = ['<div class="rates">'];~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~    if (dbs.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push('<h3>Database size</h3><div class="ghead"><span></span><span>size</span><span>per day</span><span>per 30 d</span><span>last 30 d</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      dbs.forEach(function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var f = m.f, obs = observedChange(m.pts, 30);~');
  DBMS_OUTPUT.PUT_LINE(q'~        out.push(spaceRow(m, [m.unit.fmt(f.v), m.unit.rate(f.slope),~');
  DBMS_OUTPUT.PUT_LINE(q'~          f.slope == null ? '\u2013' : sign(f.slope) + m.unit.fmt(Math.abs(f.slope) * 30),~');
  DBMS_OUTPUT.PUT_LINE(q'~          obs ? sign(obs.d) + m.unit.fmt(Math.abs(obs.d)) : '\u2013']));~');
END;
/
BEGIN
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (ts.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var fastest = ts.filter(function (m) { return fillRate(m.f) > 0; }).sort(function (a, b) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var da = a.f.dtf == null ? 1e9 : a.f.dtf, db = b.f.dtf == null ? 1e9 : b.f.dtf;~');
  DBMS_OUTPUT.PUT_LINE(q'~        return da - db || fillRate(b.f) - fillRate(a.f);~');
  DBMS_OUTPUT.PUT_LINE(q'~      }).slice(0, SPACE_TOP);~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push('<h3>Fastest-filling tablespaces</h3>' + fillsFirstHtml(ts));~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (!fastest.length) out.push('<div class="allok">No tablespace is growing</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      else out.push('<div class="ghead"><span></span><span>used</span><span>per day</span><span>per 30 d</span><span>full in</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      fastest.forEach(function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var f = m.f, r = fillRate(f);~');
  DBMS_OUTPUT.PUT_LINE(q'~        out.push(spaceRow(m, [num(f.pct, 1) + '%', m.unit.rate(r), sign(r) + fBytes(Math.abs(r) * 30), dtfFact(f, '').v]));~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push('</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- assemble ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var sections = FAMILIES.map(function (fam) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ms = (D.fits || []).filter(fam.match).map(function (f) { return buildMetric(fam, f); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    ms.sort(function (a, b) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      for (var i = 0; i < a.order.length; i++) if (a.order[i] !== b.order[i]) return a.order[i] - b.order[i];~');
  DBMS_OUTPUT.PUT_LINE(q'~      return a.name < b.name ? -1 : 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { fam: fam, ms: ms, sev: worstSev(ms.map(function (m) { return m.sev; })) };~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var present = sections.filter(function (s) { return s.ms.length; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var absent = sections.filter(function (s) { return !s.ms.length; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var metricBySeries = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~  present.forEach(function (sec) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    sec.ms.forEach(function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      [m.f.s].concat(m.fam.related || []).forEach(function (s) { metricBySeries[key(m.f.dbid, m.f.con, s)] = m; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var alerts = (D.alerts || []).slice().sort(function (a, b) { return SEV_RANK[a.sev] - SEV_RANK[b.sev]; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var nCrit = alerts.filter(function (a) { return a.sev === 'CRIT'; }).length;~');
  DBMS_OUTPUT.PUT_LINE(q'~  var nWarn = alerts.filter(function (a) { return a.sev === 'WARN'; }).length;~');
  DBMS_OUTPUT.PUT_LINE(q'~  var nSeries = present.reduce(function (n, s) { return n + s.ms.length; }, 0);~');
  DBMS_OUTPUT.PUT_LINE(q'~  var nOk = present.reduce(function (n, s) { return n + s.ms.filter(function (m) { return m.sev === 'OK'; }).length; }, 0);~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var html = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~  var dbName = (D.containers && D.containers[0] && D.containers[0].db) || M.db || '';~');
  DBMS_OUTPUT.PUT_LINE(q'~  document.title = 'Capacity \u00b7 ' + dbName + ' \u00b7 ' + (M.lastDay || '');~');
  DBMS_OUTPUT.PUT_LINE(q'~  var nCon = (D.containers || []).length;~');
  DBMS_OUTPUT.PUT_LINE(q'~  var esmLine = M.esm && M.esm.ok != null ? 'ESM models ' + M.esm.ok + ' ok, ' + (M.esm.failed || 0) + ' failed, ' + (M.esm.stale || 0) + ' stale' : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<div class="page"><header class="mast"><span><b>' + esc(dbName) + '</b>' + esc(M.host || '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~    (nCon > 1 ? ', ' + nCon + ' containers' : '') + (FIRST != null ? ', data ' + fDayY(FIRST) + ' \u2013 ' + fDayY(LAST) + ' (' + (LAST - FIRST + 1) + ' d)' : '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '</span><span>Capacity report' + (LAST != null ? ' for ' + fDayY(LAST) : '') + '</span></header>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<p class="gen"><span>Generated ' + esc((M.generated || '').slice(0, 16)) + (M.schema ? ' from schema ' + esc(M.schema) : '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~    (M.source && M.source !== 'LIVE' ? ' \u00b7 <b>' + esc(M.source) + '</b>' : '') + ' \u00b7 ' + present.length + ' metrics' + (esmLine ? ' \u00b7 ' + esmLine : '') + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<span class="tools"><button class="tbtn" id="themeBtn" type="button">Theme</button><button class="tbtn" type="button" onclick="window.print()">Print</button></span></p>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<nav class="nav"><a href="#overview">Overview</a>' + present.map(function (s) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<a class="' + SEV_CLASS[s.sev] + '" href="#' + s.fam.id + '">' + esc(s.fam.title) + '<span class="n">' + s.ms.length + '</span></a>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }).join('') + '</nav><main>');~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  (D.errors || []).forEach(function (e) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<div class="banner">Data block \u201c' + esc(e.block) + '\u201d failed: ' + esc(e.msg) + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(q'~  alerts.filter(function (a) { return a.kind === 'DATA_STALE'; }).forEach(function (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<div class="banner">' + esc(conLabel(a.dbid, a.con)) + ': ' + alertFact(a) + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(q'~  if (GEN != null && LAST != null && GEN - LAST > 3) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<div class="banner warn">Newest AWR day is ' + fDayY(LAST) + ', ' + (GEN - LAST) + ' days before this report.</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var listed = alerts.filter(function (a) { return a.sev === 'CRIT' || a.sev === 'WARN'; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var nFitOk = present.reduce(function (n, s) { return n + s.ms.filter(function (m) { return m.f.q === 'OK'; }).length; }, 0);~');
  DBMS_OUTPUT.PUT_LINE(q'~  var plural = function (n, w) { return n + ' ' + w + (n === 1 ? '' : 's'); };~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<section id="overview" class="ov">');~');
  DBMS_OUTPUT.PUT_LINE(q'~  var top = listed[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~  if (top) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tm = metricBySeries[key(top.dbid, top.con, top.s)];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var fact = /_ANOM$/.test(top.kind) ? 'unusual on ' + alertWhen(top)~');
  DBMS_OUTPUT.PUT_LINE(q'~      : alertFact(top, tm) + (top.unit === 'DAYS' || top.u === 'DAYS' ? ', on ' + fDay(Math.round(LAST + top.v)) : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<h1>' + esc(tm ? tm.name : top.s) + ' ' + fact.replace(/<[^>]*>/g, '') + '.</h1>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<h1>Nothing needs attention.</h1>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<p class="lede">' + nCrit + ' critical and ' + plural(nWarn, 'warning') + ' across ' + nSeries + ' series in ' + plural(present.length, 'metric') + '.' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    (absent.length ? ' No data for ' + absent.map(function (s) { return esc(s.fam.title); }).join(', ') + '.' : '') + '</p>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<div class="tally">' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<div' + (nCrit ? ' class="crit"' : '') + '><b>' + nCrit + '</b><span>critical</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<div' + (nWarn ? ' class="warn"' : '') + '><b>' + nWarn + '</b><span>warning</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<div><b>' + nOk + '</b><span>of ' + nSeries + ' series healthy</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<div><b>' + nFitOk + '/' + nSeries + '</b><span>fits graded OK</span></div></div>');~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  html.push(spaceHtml());~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<h3>By metric</h3><div class="idx">' + present.map(function (s) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var soon = s.ms.filter(function (m) { return m.f.dtf != null && m.f.q === 'OK' && m.f.dtf <= 365; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (x, y) { return x.f.dtf - y.f.dtf; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<a class="irow ' + SEV_CLASS[s.sev] + '" href="#' + s.fam.id + '">' + sdot(s.sev) + '<span class="it">' + esc(s.fam.title) + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<span class="ic">' + s.ms.length + '</span><span class="ih">' + headline(s.fam, s.ms) + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      sparkSvg(s.ms[0], 240, 28) + '<span class="iw">' + (soon ? stamp(LAST + soon.f.dtf) : '') + '</span></a>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }).join('') + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<h3>Needs attention <span>' + listed.length + ' open</span></h3><div class="attn">');~');
  DBMS_OUTPUT.PUT_LINE(q'~  if (!listed.length) html.push('<div class="allok">Nothing needs attention</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  listed.forEach(function (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var m = metricBySeries[key(a.dbid, a.con, a.s)];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var href = m ? '#' + m.id : '#overview';~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<a class="arow ' + SEV_CLASS[a.sev] + '" href="' + href + '">' + pill(a.sev) + '<span class="m">' + esc(m ? m.fam.title : a.kind) + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<span class="s">' + esc(m ? m.name : a.s) + ' <span>' + esc(m ? m.ctr : conLabel(a.dbid, a.con)) + '</span></span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<span class="f">' + alertFact(a, m) + '</span><span class="d">' + alertWhen(a) + '</span></a>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('</div></section>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<div class="key"><span><i class="k-hist"></i>history</span><span><i class="k-fc"></i>forecast</span><span><i class="k-bd"></i>95% band</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<span><i class="k-lim"></i>limit</span><span><i class="k-thr"></i>warning line</span><span><i class="k-un"></i>unusual day, last ' + ANOM_DAYS + ' d</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<span><i class="k-old"></i>older unusual day</span><span><i class="k-es"></i>ESM +30 d</span><span><span class="stamp">\u2192 3 Nov</span> reaches the line</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<div class="secgrid">');~');
  DBMS_OUTPUT.PUT_LINE(q'~  present.forEach(function (s) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var wide = s.ms.length > 1 || s.fam.heat;~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<section id="' + s.fam.id + '"' + (wide ? ' class="wide"' : '') + '><div class="sh"><h2>' + esc(s.fam.title) + '</h2><div class="sum">' + familySummary(s.fam, s.ms) + '</div></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var full = s.ms.slice(0, TOP_N), rest = s.ms.slice(TOP_N);~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('<div class="cards">' + full.map(cardHtml).join('') + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (rest.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      html.push('<div class="rows"><h3>' + rest.length + ' more ' + s.fam.noun + (rest.length === 1 ? '' : 's') + '</h3>' + rest.map(rowHtml).join('') + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    html.push('</section>');~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(q'~  html.push('</div></main><footer class="foot"><span>' + esc(M.db) + '</span><span>schema ' + esc(M.schema) + '</span><span>suite ' + esc(K.suiteVersion || '') + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~    '<span>' + esc(M.run || '') + '</span><span>read-only</span><span>' + esc(M.file || '') + '</span></footer></div>');~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  document.getElementById('app').innerHTML = html.join('');~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- interaction ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function nearest(pts, x) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var best = null, bd = Infinity;~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) { if (p.y != null && Math.abs(p.x - x) < bd) { bd = Math.abs(p.x - x); best = p; } });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return best;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function anomalyNote(m, s, day) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var hit = m.anoms.filter(function (a) { return a.s === s && dayN(a.ts) === day && a.ak !== 'CPU_SHIFT'; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!hit.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var z = hit.reduce(function (b, a) { return Math.abs(a.z) > Math.abs(b.z) ? a : b; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.fam.id === 'tablespaces') return 'unusual growth ' + sign(z.v) + fBytes(Math.abs(z.v)) + ', usual ' + fBytes(z.e) + ' \u00b7 z ' + num(z.z, 1);~');
  DBMS_OUTPUT.PUT_LINE(q'~    return 'unusual, usual ' + m.unit.fmt(z.e) + ' \u00b7 z ' + num(z.z, 1);~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  Array.prototype.forEach.call(document.querySelectorAll('.chart'), function (el) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var spec = CHARTS[+el.getAttribute('data-chart')];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var svg = el.querySelector('svg'), tip = el.querySelector('.tip');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var hx = svg.querySelector('.hx'), hd = svg.querySelector('.hd'), hit = svg.querySelector('.hit');~');
  DBMS_OUTPUT.PUT_LINE(q'~    function hide() { tip.classList.remove('on'); hx.setAttribute('visibility', 'hidden'); hd.setAttribute('visibility', 'hidden'); }~');
  DBMS_OUTPUT.PUT_LINE(q'~    hit.addEventListener('mouseleave', hide);~');
  DBMS_OUTPUT.PUT_LINE(q'~    hit.addEventListener('mousemove', function (ev) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var r = svg.getBoundingClientRect();~');
  DBMS_OUTPUT.PUT_LINE(q'~      var vx = (ev.clientX - r.left) / r.width * W;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = spec.x0 + (vx - ML) / (W - ML - MR) * (spec.x1 - spec.x0);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var lines = [], px, py;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (x <= LAST + 0.5) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var p = nearest(spec.lines[0].pts, x);~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (!p) return hide();~');
  DBMS_OUTPUT.PUT_LINE(q'~        px = spec.xs(p.x); py = spec.ys(p.y);~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push('<b>' + fWDay(p.x) + ' ' + dateOf(p.x).getUTCFullYear() + '</b>');~');
  DBMS_OUTPUT.PUT_LINE(q'~        spec.lines.forEach(function (l) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          var q = nearest(l.pts, p.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (q && q.x === p.x) lines.push((l.label ? esc(l.label) + ' ' : '') + '<b>' + spec.unit.fmt(q.y) + '</b>' + (spec.m.f.lim && l.role === 0 && !spec.pctAxis ? ' \u00b7 ' + num(q.y / (q.lim || spec.m.f.lim) * 100, 1) + '%' : ''));~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (q && q.x === p.x && (q.a === 1 || q.a === -1)) {~');
  DBMS_OUTPUT.PUT_LINE(q'~            var note = anomalyNote(spec.m, l.s, q.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~            lines.push('<span class="a">' + esc(note || 'unusual') + '</span>');~');
  DBMS_OUTPUT.PUT_LINE(q'~          }~');
  DBMS_OUTPUT.PUT_LINE(q'~        });~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var fc = spec.fc;~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (fc.length < 2) return hide();~');
  DBMS_OUTPUT.PUT_LINE(q'~        var i = 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~        while (i < fc.length - 1 && fc[i].x < x) i++;~');
  DBMS_OUTPUT.PUT_LINE(q'~        var a = fc[i - 1], b = fc[i], t = Math.max(0, Math.min(1, (x - a.x) / (b.x - a.x)));~');
  DBMS_OUTPUT.PUT_LINE(q'~        var xd = Math.round(a.x + t * (b.x - a.x));~');
  DBMS_OUTPUT.PUT_LINE(q'~        t = (xd - a.x) / (b.x - a.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~        var y = a.y + t * (b.y - a.y);~');
  DBMS_OUTPUT.PUT_LINE(q'~        var lo = a.lo != null ? a.lo + t * ((b.lo != null ? b.lo : b.y) - a.lo) : (b.lo != null ? a.y + t * (b.lo - a.y) : null);~');
  DBMS_OUTPUT.PUT_LINE(q'~        var hi = a.hi != null ? a.hi + t * ((b.hi != null ? b.hi : b.y) - a.hi) : (b.hi != null ? a.y + t * (b.hi - a.y) : null);~');
  DBMS_OUTPUT.PUT_LINE(q'~        px = spec.xs(xd); py = spec.ys(y);~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push('<b>' + fWDay(xd) + ' ' + dateOf(xd).getUTCFullYear() + '</b> \u00b7 +' + (xd - LAST) + ' d');~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push('forecast <b>' + spec.unit.fmt(y) + '</b>');~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (lo != null && hi != null) lines.push('95% ' + spec.unit.fmt(lo) + ' \u2013 ' + spec.unit.fmt(hi));~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~      hx.setAttribute('x1', px); hx.setAttribute('x2', px); hx.setAttribute('visibility', 'visible');~');
  DBMS_OUTPUT.PUT_LINE(q'~      hd.setAttribute('cx', px); hd.setAttribute('cy', py); hd.setAttribute('visibility', 'visible');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.innerHTML = lines.join('<br>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = Math.max(70, Math.min(r.width - 70, px / W * r.width)) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = (py / H * r.height) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.classList.add('on');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  Array.prototype.forEach.call(document.querySelectorAll('.heat'), function (el) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tip = document.createElement('div');~');
  DBMS_OUTPUT.PUT_LINE(q'~    tip.className = 'tip';~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.style.position = 'relative';~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.appendChild(tip);~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.addEventListener('mousemove', function (ev) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var c = ev.target;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (!c.classList || !c.classList.contains('hc')) { tip.classList.remove('on'); return; }~');
  DBMS_OUTPUT.PUT_LINE(q'~      var r = el.getBoundingClientRect(), cr = c.getBoundingClientRect();~');
  DBMS_OUTPUT.PUT_LINE(q'~      var v = c.getAttribute('data-v'), f = +c.getAttribute('data-f'), h = +c.getAttribute('data-h');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.innerHTML = '<b>' + fWDay(+c.getAttribute('data-d')) + ' ' + (h < 10 ? '0' : '') + h + ':00</b> ' + (v === '' ? 'no data' : num(+v, 1) + '%') +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (f === 1 ? '<br><span class="a">busier than this hour usually is</span>' : f === -1 ? '<br><span class="a">quieter than this hour usually is</span>' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = (cr.left - r.left + cr.width / 2) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = (cr.top - r.top) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.classList.add('on');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.addEventListener('mouseleave', function () { tip.classList.remove('on'); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var root = document.documentElement, TK = 'cap-theme';~');
  DBMS_OUTPUT.PUT_LINE(q'~  try { var saved = localStorage.getItem(TK); if (saved) root.setAttribute('data-theme', saved); } catch (e) { /* storage blocked */ }~');
  DBMS_OUTPUT.PUT_LINE(q'~  document.getElementById('themeBtn').onclick = function () {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var cur = root.getAttribute('data-theme');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var dark = cur ? cur === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var next = dark ? 'light' : 'dark';~');
  DBMS_OUTPUT.PUT_LINE(q'~    root.setAttribute('data-theme', next);~');
  DBMS_OUTPUT.PUT_LINE(q'~    try { localStorage.setItem(TK, next); } catch (e) { /* storage blocked */ }~');
  DBMS_OUTPUT.PUT_LINE(q'~  };~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  if ('IntersectionObserver' in window) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var links = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    Array.prototype.forEach.call(document.querySelectorAll('.nav a'), function (a) { links[a.getAttribute('href').slice(1)] = a; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var io = new IntersectionObserver(function (entries) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      entries.forEach(function (e) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (e.isIntersecting && links[e.target.id]) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          Object.keys(links).forEach(function (k) { links[k].classList.toggle('on', k === e.target.id); });~');
  DBMS_OUTPUT.PUT_LINE(q'~        }~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }, { rootMargin: '-60px 0px -70% 0px' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    Array.prototype.forEach.call(document.querySelectorAll('main section'), function (s) { io.observe(s); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~})();~');
  DBMS_OUTPUT.PUT_LINE(q'~</script>~');
  DBMS_OUTPUT.PUT_LINE(q'~</body>~');
  DBMS_OUTPUT.PUT_LINE(q'~</html>~');
END;
/
